package com.neighbormarket.ai;
import com.fasterxml.jackson.databind.ObjectMapper;import com.neighbormarket.domain.TradeType;import org.junit.jupiter.api.Test;import org.springframework.http.HttpStatus;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class PricingServiceTest {private final ObjectMapper json=new ObjectMapper();private final Clock clock=Clock.fixed(Instant.parse("2026-09-29T00:00:00Z"),ZoneOffset.UTC);
 @Test void needMoreInfoIsAccepted(){var r=service("{\"status\":\"NEED_MORE_INFO\",\"missingFields\":[\"condition\"],\"questions\":[\"成色情况如何？\"]}").estimate(request(TradeType.FIXED_PRICE),"a");assertEquals(PricingModels.Status.NEED_MORE_INFO,r.status());assertEquals("condition",r.missingFields().get(0));}
 @Test void validEstimateIsAccepted(){var r=service(valid()).estimate(request(TradeType.FIXED_PRICE),"a");assertEquals(PricingModels.Status.ESTIMATE,r.status());assertEquals(80,r.recommendedPrice().intValue());}
 @Test void invalidJsonIsRejected(){assertCode("AI_INVALID_RESPONSE",()->service("not-json").estimate(request(TradeType.FIXED_PRICE),"a"));}
 @Test void negativePriceIsRejected(){assertCode("AI_INVALID_RESPONSE",()->service(valid().replace("60","-1")).estimate(request(TradeType.FIXED_PRICE),"a"));}
 @Test void incorrectPriceOrderIsRejected(){assertCode("AI_INVALID_RESPONSE",()->service(valid().replace("\"recommendedPrice\":80","\"recommendedPrice\":120")).estimate(request(TradeType.FIXED_PRICE),"a"));}
 @Test void priceAboveLimitIsRejected(){assertCode("AI_INVALID_RESPONSE",()->service(valid().replace("\"maxPrice\":100","\"maxPrice\":1000001")).estimate(request(TradeType.FIXED_PRICE),"a"));}
 @Test void nonFixedPriceIsRejectedBeforeGateway(){assertCode("AI_FIXED_PRICE_ONLY",()->service(valid()).estimate(request(TradeType.FREE),"a"));assertCode("AI_FIXED_PRICE_ONLY",()->service(valid()).estimate(request(TradeType.NEGOTIABLE),"b"));}
 @Test void repeatedRequestIsRateLimited(){var s=service(valid());s.estimate(request(TradeType.FIXED_PRICE),"a");var e=assertThrows(PricingException.class,()->s.estimate(request(TradeType.FIXED_PRICE),"a"));assertEquals(HttpStatus.TOO_MANY_REQUESTS,e.status());}
 private PricingService service(String response){return new PricingService(r->response,json,clock,Duration.ofSeconds(10));}private PricingModels.Request request(TradeType type){return new PricingModels.Request(type,"九阳电磁炉","家电","使用约一年，功能正常",null,null,"一年","轻微使用痕迹","未发现","配件齐全");}private String valid(){return "{\"status\":\"ESTIMATE\",\"minPrice\":60,\"maxPrice\":100,\"recommendedPrice\":80,\"rationale\":\"基于用户描述\",\"factors\":[\"使用一年\"],\"uncertainty\":\"未查询实时行情\",\"confidence\":\"MEDIUM\"}";}private void assertCode(String code,Runnable action){var e=assertThrows(PricingException.class,action::run);assertEquals(code,e.code());}
}